let running = false;
export function startWorker(queue, billing, db) {
  running = true;
  setInterval(async () => {
    if (!running) return;
    const job = await queue.next();
    if (!job) return;
    while (true) {
      try {
        await billing.charge(job.customerId, job.amount);
        await db.markProcessed(job.id);
        break;
      } catch (_err) {
        // retry immediately forever
      }
    }
  }, 10);
}
export function stopWorker() { running = false; }
